/*
 * A191142  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x+2 and 4x are in a.
 * https://oeis.org/A191142
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1; if x∈a then 3x+2 and 4x∈a – computed by generating the
 *            sequence in ascending order with a min‑heap (priority queue)
 * Range:     u8 n <= 13, u16 n <= 568, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* Static cache for generated terms */
static seq_t *seq_cache = NULL;
static size_t seq_cap = 0;
static size_t seq_len = 0;
/* largest n for which seq_cache has been generated */
static idx_t max_n_computed = 0;

/* Min‑heap for candidates */
static seq_t *heap = NULL;
static size_t heap_cap = 0;
static size_t heap_len = 0;

/* Ensure heap has enough capacity */
static void heap_ensure_cap(void)
{
    if (heap_len == heap_cap) {
        size_t new_cap = heap_cap ? heap_cap * 2 : 256;
        seq_t *tmp = (seq_t *)realloc(heap, new_cap * sizeof(seq_t));
        heap = tmp;
        heap_cap = new_cap;
    }
}

/* Push a value onto the min‑heap */
static void heap_push(seq_t val)
{
    heap_ensure_cap();
    size_t i = heap_len++;
    heap[i] = val;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        seq_t t = heap[p]; heap[p] = heap[i]; heap[i] = t;
        i = p;
    }
}

/* Pop the smallest value from the heap */
static seq_t heap_pop(void)
{
    seq_t min = heap[0];
    heap_len--;
    if (heap_len > 0) {
        heap[0] = heap[heap_len];
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            size_t r = l + 1;
            size_t smallest = i;
            if (l < heap_len && heap[l] < heap[smallest]) smallest = l;
            if (r < heap_len && heap[r] < heap[smallest]) smallest = r;
            if (smallest == i) break;
            seq_t t = heap[i]; heap[i] = heap[smallest]; heap[smallest] = t;
            i = smallest;
        }
    }
    return min;
}

/* Ensure the sequence cache has enough capacity */
static void seq_ensure_cap(size_t needed)
{
    if (seq_cap < needed) {
        size_t new_cap = seq_cap ? seq_cap * 2 : 256;
        while (new_cap < needed) new_cap *= 2;
        seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
        seq_cache = tmp;
        seq_cap = new_cap;
    }
}

/* Generate the sequence up to index n (1‑based) */
static void generate_up_to(idx_t n)
{
    if (n <= max_n_computed) return;

    /* Initialisation on first call */
    if (seq_cache == NULL) {
        seq_ensure_cap(n);
        seq_len = 0;
        heap_cap = 256;
        heap = (seq_t *)malloc(heap_cap * sizeof(seq_t));
        heap_len = 0;
        heap_push((seq_t)1);          /* seed value a(1) */
    }

    /* Generate until we have n terms */
    while (seq_len < (size_t)n) {
        seq_t cur = heap_pop();

        /* Skip duplicates */
        if (seq_len == 0 || cur != seq_cache[seq_len - 1]) {
            seq_ensure_cap(seq_len + 1);
            seq_cache[seq_len++] = cur;

            /* Push new candidates */
            heap_push(cur * (seq_t)4);
            heap_push(cur * (seq_t)3 + (seq_t)2);
        }
    }
    max_n_computed = n;
}

/* Public function – external linkage */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for n = 0, return 0 for safety */
    generate_up_to(n);
    return seq_cache[(size_t)n - 1];
}
